import { Routes, Route } from "react-router-dom"; // 1. Import components
import Home from "./Home";
// Assume you have these components
import Navbar from "./Navbar"; 
import Product from "./Product"; 

export default function App() {
  return (
    <>
      {/* 2. Place the Navbar outside of Routes so it appears on all pages */}
      <Navbar /> 

      {/* 3. Define the routing area */}
      <Routes>
        {/* Route for the Home component */}
        <Route path="/" element={<Home />} />

        {/* Route for the Product component */}
        <Route path="/products" element={<Product />} />

        {/* You can add a 404/Catch-all route if needed */}
        {/* <Route path="*" element={<NotFoundPage />} /> */}
      </Routes>
    </>
  );
}
